const ctx = pendulumCanvas.getContext('2d');

// Initialize pendulum state
let theta = 0; // initial angle (radians)
let omega = 0; // initial angular velocity (rad/s)
let dt = 0.01; // time step (seconds)
let t = 0; // current time (seconds)

