function animate() {
  requestAnimationFrame(animate);
  simulate();
  ctx.clearRect(0, 0, canvasWidth, canvasHeight);
  drawPendulum();
}

// Simulation loop
function simulate() {
  // Update pendulum state
  const thetaNew = theta + omega * dt;
  const omegaNew = (-G / L) * Math.sin(theta) * dt;
  theta = thetaNew;
  omega = omegaNew;
  t += dt;

  // Check if pendulum has come to rest
  if (Math.abs(omega) < 0.01) {
